#include <vector>
#include <iterator>
#include <type_traits>

template <typename Iterator1, typename Iterator2>
auto operator-(const std::reverse_iterator<Iterator1>& x,
               const std::reverse_iterator<Iterator2>& y)
    -> decltype(y.base() - x.base()) {
    return y.base() - x.base();
}

int main() {
    std::vector<int> v = {1, 2, 3, 4, 5};
    auto rbegin = v.rbegin();
    auto rend = v.rend();
    auto diff = rbegin - rend; // Uses the overloaded operator-
    return 0;
}
